ies":["actor"],"components":["person"]},"participants":{"board":{"categories":["schedule"],"components":["lesson_queue"]}},"parameters":{},"checks":[{"label":"the dispatcher is scheduling the lesson","left":{"participant":{"name":"actor","path":"components.person.role"}},"op":"eq","right":{"literal":"dispatcher"}},{"label":"the lesson board is where the dispatcher is","left":{"participant":{"name":"actor","path":"location.location_id"}},"op":"eq","right":{"participant":{"name":"board","path":"location.location_id"}}}],"effects":[{"participant":"board","path":"components.lesson_queue.waiting_lessons","op":"add","value":{"literal":1}}],"limits":["Only a dispatcher may schedule lessons.","This action does not teach or complete a lesson."],"tests":["A dispatcher at the board’s place adds one waiting lesson.","A non-dispatcher or a dispatcher at another place is refused."],"semantic_bindings":["board is the lesson board receiving the scheduled lesson."]},{"schema_version":"world-substrate-action-mechanic/v0","mechanic_id":"teach-ground-lesson","version":"1","action_kind":"teach-ground-lesson","rationale":"A ground lesson is taught by an instructor to the represented trainee at their shared place.","actor_selector":{"categories":["actor"],"components":["person"]},"participants":{"trainee":{"categories":["trainee","actor"],"components":["person","training"]}},"parameters":{},"checks":[{"label":"the instructor is teaching","left":{"participant":{"name":"actor","path":"components.person.role"}},"op":"eq","right":{"literal":"instructor"}},{"label":"Sam is the trainee","left":{"action_field":"trainee"},"op":"eq","right":{"entity_id":"trainee"}},{"label":"Sam is where the instructor is","left":{"participant":{"name":"trainee","path":"location.location_id"}},"op":"eq","right":{"participant":{"name":"actor","path":"location.location_id"}}}],"effects":[{"participant":"trainee","path":"components.person.energy","op":"subtract","value":{"literal":1}}],"limits":["Only the represented trainee Sam can receive this lesson.","The represented state has no ground-lesson completion field, so this action does not change flight completion."],"tests":["The instructor can teach Sam when they share a place.","Teaching another person or teaching from a different place is refused."],"semantic_bindings":["trainee is Sam, the recipient of the ground lesson."]},{"schema_version":"world-substrate-action-mechanic/v0","mechanic_id":"inspect-aircraft","version":"1","action_kind":"inspect-helicopter","rationale":"Inspecting the represented helicopter increments its inspection count when the mechanic and helicopter are together.","actor_selector":{"categories":["actor"],"components":["person"]},"participants":{"aircraft":{"categories":["aircraft"],"components":["aircraft"]}},"parameters":{},"checks":[{"label":"the mechanic is inspecting","left":{"participant":{"name":"actor","path":"components.person.role"}},"op":"eq","right":{"literal":"mechanic"}},{"label":"the helicopter is where the mechanic is","left":{"participant":{"name":"actor","path":"location.location_id"}},"op":"eq","right":{"participant":{"name":"aircraft","path":"location.location_id"}}}],"effects":[{"participant":"aircraft","path":"components.aircraft.inspection_count","op":"add","value":{"literal":1}}],"limits":["The inspection count records inspections; it does not represent a separate airworthiness certification."],"tests":["The mechanic can inspect the helicopter when both are in the same place.","Inspection is refused when the mechanic is elsewhere or is not a mechanic."],"semantic_bindings":["aircraft is the helicopter being inspected."]},{"schema_version":"world-substrate-action-mechanic/v0","mechanic_id":"fly-training-lesson","version":"1","action_kind":"fly-training-lesson","rationale":"A training flight requires the instructor, Sam, and helicopter to be together, with fuel and a prior inspection represented; the flight uses fuel and increments Sam’s completed flights.","actor_selector":{"categories":["actor"],"components":["person"]},"participants":{"trainee":{"categories":["trainee","actor"],"components":["person","training"]},"aircraft":{"categories":["aircraft"],"components":["aircraft"]},"instructor":{"categories":["instructor","actor"],"components":["person"]}},"parameters":{},"checks":[{"label":"the flight instructor is leading the lesson","left":{"participant":{"name":"actor","path":"components.person.role"}},"op":"eq","right":{"literal":"instructor"}},{"label":"Sam is the trainee","left":{"action_field":"trainee"},"op":"eq","right":{"entity_id":"trainee"}},{"label":"the named instructor is leading the lesson","left":{"action_field":"instructor"},"op":"eq","right":{"entity_id":"actor"}},{"label":"Sam is with the instructor","left":{"participant":{"name":"trainee","path":"location.location_id"}},"op":"eq","right":{"participant":{"name":"actor","path":"location.location_id"}}},{"label":"the helicopter is with the instructor","left":{"participant":{"name":"aircraft","path":"location.location_id"}},"op":"eq","right":{"participant":{"name":"actor","path":"location.location_id"}}},{"label":"the helicopter has fuel","left":{"participant":{"name":"aircraft","path":"components.aircraft.fuel"}},"op":"gt","right":{"literal":0}},{"label":"the helicopter has been inspected","left":{"participant":{"name":"aircraft","path":"components.aircraft.inspection_count"}},"op":"gt","right":{"literal":0}}],"effects":[{"participant":"aircraft","path":"components.aircraft.fuel","op":"subtract","value":{"literal":1}},{"participant":"trainee","path":"components.training.flights_completed","op":"add","value":{"literal":1}},{"participant":"trainee","path":"components.person.energy","op":"subtract","value":{"literal":1}}],"limits":["The named instructor must be the acting instructor.","The represented state has no way to refuel the helicopter; flights stop when its fuel is exhausted.","A prior inspection is required; this action does not perform one."],"tests":["After a mechanic has inspected the helicopter, an instructor can complete a flight with Sam when all three are together and fuel remains.","The flight is refused if fuel is empty, the helicopter has never been inspected, Sam is elsewhere, or the acting person is not the named instructor."],"semantic_bindings":["trainee is Sam.","aircraft is the helicopter used for the flight.","instructor must be the acting person."]},{"schema_version":"world-substrate-action-mechanic/v0","mechanic_id":"drink-water","version":"1","action_kind":"drink-water","rationale":"Drinking consumes the represented glass of water, clearing its ownership and portable state so the used-up drink cannot be consumed repeatedly.","actor_selector":{"categories":["actor"],"components":["person"]},"participants":{"drink":{"categories":["drink"],"components":[]}},"parameters":{},"checks":[{"label":"the water is where the drinker is","left":{"participant":{"name":"drink","path":"location.location_id"}},"op":"eq","right":{"participant":{"name":"actor","path":"location.location_id"}}},{"label":"the glass is still available to drink","left":{"participant":{"name":"drink","path":"portable.portable"}},"op":"eq","right":{"literal":true}}],"effects":[{"participant":"drink","path":"portable.portable","op":"set","value":{"literal":false}},{"participant":"drink","path":"ownership.owner_ref","op":"set","value":{"literal":null}}],"limits":["The represented glass of water is consumed once; no process replenishes it.","This action does not move the drink or change the drinker’s energy because no such consequence is represented."],"tests":["An actor at the glass’s place can drink it once.","Drinking is refused when the glass is elsewhere or has already been consumed."],"semantic_bindings":["drink is the glass of water being consumed."]}],"processes":[{"process_id":"passage-becomes-usable","rationale":"The represented passage is the only route between the office and hangar. Making it usable enables the described movement action; this process does not move any person or object.","selector":{"categories":["barrier"],"components":["passage"]},"checks":[{"label":"the passage connects the represented office and hangar","left":{"participant":{"name":"it","path":"components.passage.place_a"}},"op":"eq","right":{"entity_id":"it"}},{"label":"the passage is currently closed","left":{"participant":{"name":"it","path":"components.passage.can_pass"}},"op":"eq","right":{"literal":false}}],"effects":[{"participant":"it","path":"components.passage.can_pass","op":"set","value":{"literal":true}}]},{"process_id":"aircraft-fuel-renews","rationale":"Fuel is the represented consumable needed for ongoing training flights; this slow ongoing renewal keeps the helicopter usable without creating a completed flight or moving fuel between holders.","timing":"each_round","selector":{"categories":["aircraft"],"components":["aircraft"]},"checks":[{"label":"the helicopter has less than ten units of fuel","left":{"participant":{"name":"it","path":"components.aircraft.fuel"}},"op":"lt","right":{"literal":10}}],"effects":[{"participant":"it","path":"components.aircraft.fuel","op":"add","value":{"literal":1}}]}],"terminal":null}", "role": "assistant"}, {"content": "The local causal compiler rejected that proposal. Compiler error: ActionDeclarationError: effects[1] cannot set string from null. Return a corrected JSON object only. State paths in participant/path and effect/path fields must be copied EXACTLY from allowed_state_paths; do not abbreviate component containers (for example use portable.portable, not portable).", "role": "user"}], "prompt_ref": null, "control": {"timeout": 0, "num_retries": 1, "reasoning_effort": "low", "api_base": null, "base_delay": 1.0, "max_delay": 30.0, "retry_on": null, "fallback_models": null, "manual_fallback": null, "execution_mode": "text", "structured_output_mode": null, "structured_contract_ref": null, "retry_policy": {"max_retries": 1, "base_delay": 1.0, "max_delay": 30.0, "retry_on": null, "on_retry": null, "backoff": null, "should_retry": null}, "cache_policy": {"mode": "disabled"}, "max_budget": 0.2}, "kwargs": {"max_tokens": 16000, "model_justification": "World Builder rules retry: the first rules did not let the described world reach its finish line; the retry uses WORLD_BUILDER_STRONG_MODEL (gpt-6-luna measured 23/24 on 2026-10-23, against gpt-5.6-luna 11/24 and gpt-5.6-sol 6/6 on 2026-10-05).", "model_policy": "enforce_allowlist"}, "response_model_fqn": null, "response_model_schema": null}, "replay": {"unsupported_keys": []}}

